CREATE TABLE Roles (id INTEGER PRIMARY KEY, name VARCHAR(50) NOT NULL UNIQUE);
CREATE TABLE Users (id INTEGER PRIMARY KEY, role_id INTEGER NOT NULL REFERENCES Roles(id), name VARCHAR(100) NOT NULL, email VARCHAR(150) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, coupon_code VARCHAR(50), coupon_percent DECIMAL(5,2) DEFAULT 0);
CREATE TABLE Categories (id INTEGER PRIMARY KEY, name VARCHAR(100) NOT NULL UNIQUE);
CREATE TABLE Products (id INTEGER PRIMARY KEY, category_id INTEGER NOT NULL REFERENCES Categories(id), name VARCHAR(150) NOT NULL, description TEXT, image_url TEXT, stock_quantity INTEGER NOT NULL DEFAULT 0, price DECIMAL(10,2) NOT NULL, discount_percent DECIMAL(5,2) DEFAULT 0);
CREATE TABLE Orders (id INTEGER PRIMARY KEY, user_id INTEGER NOT NULL REFERENCES Users(id), product_id INTEGER NOT NULL REFERENCES Products(id), ordered_at TIMESTAMP NOT NULL, status VARCHAR(30) NOT NULL);
CREATE TABLE Payments (id INTEGER PRIMARY KEY, order_id INTEGER NOT NULL REFERENCES Orders(id), amount DECIMAL(10,2) NOT NULL, status VARCHAR(30) NOT NULL, paid_at TIMESTAMP);
